/**
 * @file images.h
 * @brief Image resource table generated by WCHGUIDesigner.
 * @note Byte order: Big Endian
 */

#ifndef _IMAGES_H_
#define _IMAGES_H_

#include <stdint.h>
#include <stddef.h>

#define WUI_INTERNAL_FLASH 1

typedef enum {
    IMAGE_NONE = 0xFFFF,
    // === Raw images (0b000) ===
    IMAGE_TEXT_WUI_PAGE_1_COMPONENT_001 = MAKE_IMAGE_ID(IMAGE_TYPE_RAW, 0),
    // === RLE images (0b001) ===
    IMAGE_IMG_2025_12_24_212900_445 = MAKE_IMAGE_ID(IMAGE_TYPE_RLE, 1),
} image_index_t;

static const image_info_t image_table[] = {
    {  // IMAGE_TEXT_WUI_PAGE_1_COMPONENT_001
        .addr      = 0x00000634,
        .width     = 77,
        .height    = 28,
        .data_size = 4312,
    },
    {  // IMAGE_IMG_2025_12_24_212900_445
        .addr      = 0x00000000,
        .width     = 50,
        .height    = 50,
        .data_size = 1587,
    },
};

#define RAW_IMAGE_COUNT   1
#define RLE_IMAGE_COUNT   1
#define CLUT_IMAGE_COUNT  0
#define CLUT4_IMAGE_COUNT 0
#define IMAGE_COUNT       2

static inline const image_info_t* get_image(image_index_t index) {
    uint16_t idx = IMAGE_GET_INDEX(index);
    if (idx >= IMAGE_COUNT) return NULL;
    return &image_table[idx];
}

#endif /* _IMAGES_H_ */
